import { act, fireEvent, render, screen, waitFor } from '@testing-library/react';
import React from 'react';
import FileMultiUploader from './FileMultiUploader';
import { generateUUID } from './utils/generateUUID';

jest.mock('./utils/generateUUID', () => ({
  generateUUID: jest.fn(),
}));

jest.useFakeTimers();

const validFilesMock = [
  {
    fileContent: {
      name: 'validFileMock1',
      size: 10000000,
      type: 'text/plain',
    },
    id: 'validFileMockId1',
    name: 'validFileMock1',
    size: 10000000,
    type: 'text/plain',
    loadingStatus: 'uploaded',
    progress: 100,
    errors: [],
  },
  {
    fileContent: {
      name: 'validFileMock2',
      size: 35000000,
      type: 'image/png',
    },
    id: 'validFileMockId2',
    name: 'validFileMock2',
    size: 35000000,
    type: 'image/png',
    loadingStatus: 'uploaded',
    progress: 100,
    errors: ['File max size error'],
  },
  {
    fileContent: {
      name: 'validFileMock3',
      size: 2000000,
      type: 'image/png',
    },
    id: 'validFileMockId3',
    name: 'validFileMock3',
    size: 2000000,
    type: 'image/png',
    loadingStatus: 'uploaded',
    progress: 100,
    errors: [],
    url: 'url-mock',
  },
];

describe('FileMultiUploader', () => {
  window.URL.createObjectURL = jest.fn();
  beforeEach(() => {
    jest.clearAllMocks();
  });

  it('should render correctly with custom texts', () => {
    render(
      <FileMultiUploader
        title="Drag your file(s) here or "
        message="Accepted files: CSV"
        inputLabel="Search"
      />
    );
    expect(screen.getByText('Drag your file(s) here or')).toBeInTheDocument();
    expect(screen.getByText('Accepted files: CSV')).toBeInTheDocument();
    expect(screen.getByText('Search')).toBeInTheDocument();
  });

  it('should render correctly when passing multiple files on value', () => {
    render(
      <FileMultiUploader value={validFilesMock} multiple title="Drag your file(s) here or " />
    );
    expect(screen.getByText('Drag your file(s) here or')).toBeInTheDocument();
    expect(screen.getByText(validFilesMock[0].fileContent.name)).toBeInTheDocument();
    expect(screen.getByText(validFilesMock[1].fileContent.name)).toBeInTheDocument();
    expect(screen.getByText(validFilesMock[2].fileContent.name)).toBeInTheDocument();
  });

  it('should call onDrop when a file is dropped', () => {
    const mockOnDrop = jest.fn();
    const mockOnChange = jest.fn();
    generateUUID.mockReturnValueOnce('1234');
    render(<FileMultiUploader onDrop={mockOnDrop} onChange={mockOnChange} />);
    const dropzone = screen.getByTestId('drag-and-drop-area');
    fireEvent.dragOver(dropzone);
    fireEvent.drop(dropzone, {
      dataTransfer: { files: [new File(['dummy content'], 'example.txt', { type: 'text/plain' })] },
    });
    fireEvent.dragLeave(dropzone);
    expect(mockOnDrop).toHaveBeenCalled();
    expect(mockOnChange).toHaveBeenCalled();
  });

  it('should call onDrop when multiple files are dropped', () => {
    const mockOnDrop = jest.fn();
    generateUUID
      .mockReturnValueOnce('1234')
      .mockReturnValueOnce('5678')
      .mockReturnValueOnce('9123');
    render(<FileMultiUploader multiple onDrop={mockOnDrop} />);
    const dropzone = screen.getByTestId('drag-and-drop-area');
    fireEvent.dragOver(dropzone);
    fireEvent.drop(dropzone, {
      dataTransfer: {
        files: [
          new File(['dummy content 1'], 'example1.txt', { type: 'text/plain' }),
          new File(['dummy content 2'], 'example2.txt', { type: 'text/plain' }),
          new File(['dummy content 3'], 'example3.txt', { type: 'text/plain' }),
        ],
      },
    });
    fireEvent.dragLeave(dropzone);
    expect(mockOnDrop).toHaveBeenCalled();
  });

  it('should call onDrop when a file is uploaded via the input', () => {
    const mockOnDrop = jest.fn();
    generateUUID.mockReturnValueOnce('1234');
    render(<FileMultiUploader onDrop={mockOnDrop} />);
    const fileInput = screen.getByTestId('file-uploader-input');
    const file = new File(['dummy content'], 'example.txt', { type: 'text/plain' });
    fireEvent.change(fileInput, { target: { files: [file] } });
    expect(mockOnDrop).toHaveBeenCalledWith([
      {
        id: '1234',
        name: 'example.txt',
        size: 13,
        type: 'text/plain',
        fileContent: file,
        loadingStatus: 'uploaded',
        progress: 100,
        errors: [],
        url: '',
      },
    ]);
  });

  it('should call onClean when a file is cleaned', () => {
    const mockOnClean = jest.fn();
    const mockOnChange = jest.fn();
    render(
      <FileMultiUploader
        value={[validFilesMock[0]]}
        onClean={mockOnClean}
        onChange={mockOnChange}
      />
    );
    const cleanButton = screen.getByTestId('clean-button');
    fireEvent.click(cleanButton);
    expect(mockOnClean).toHaveBeenCalled();
    expect(mockOnChange).toHaveBeenCalled();
  });

  it('should call onUpload when a file is uploaded', () => {
    const mockOnUpload = jest.fn();
    const mockOnChange = jest.fn();
    generateUUID.mockReturnValueOnce('1234');
    render(<FileMultiUploader onUpload={mockOnUpload} onChange={mockOnChange} />);
    const dropzone = screen.getByTestId('drag-and-drop-area');
    fireEvent.dragOver(dropzone);
    fireEvent.drop(dropzone, {
      dataTransfer: { files: [new File(['dummy content'], 'example.txt', { type: 'text/plain' })] },
    });
    fireEvent.dragLeave(dropzone);
    expect(mockOnUpload).toHaveBeenCalled();
    expect(mockOnChange).toHaveBeenCalled();
  });

  it('should call onPreview when a file has a preview', () => {
    const mockOnPreview = jest.fn();
    render(<FileMultiUploader value={[validFilesMock[0]]} onPreview={mockOnPreview} />);
    const previewButton = screen.getByTestId('preview-button');
    fireEvent.click(previewButton);
    expect(mockOnPreview).toHaveBeenCalled();
  });

  it('should call customFileValidator when a file is uploaded', () => {
    const mockCustomFileValidator = jest.fn();
    generateUUID.mockReturnValueOnce('1234');
    render(<FileMultiUploader customFileValidator={mockCustomFileValidator} />);
    const dropzone = screen.getByTestId('drag-and-drop-area');
    const file = new File(['dummy content'], 'example.txt', { type: 'text/plain' });
    fireEvent.dragOver(dropzone);
    fireEvent.drop(dropzone, { dataTransfer: { files: [file] } });
    fireEvent.dragLeave(dropzone);
    expect(mockCustomFileValidator).toHaveBeenCalledWith(file);
  });

  it('should call onProgress when a file is uploaded', () => {
    const mockOnProgress = jest.fn();
    generateUUID.mockReturnValueOnce('1234');
    render(<FileMultiUploader onProgress={mockOnProgress} />);
    const dropzone = screen.getByTestId('drag-and-drop-area');
    const file = new File(['dummy content'], 'example.txt', { type: 'text/plain' });
    fireEvent.drop(dropzone, { dataTransfer: { files: [file] } });
    expect(mockOnProgress).toHaveBeenCalled();
  });

  it('should show feedback message when a file is uploaded with progress', () => {
    const mockValue = [
      {
        fileContent: {
          name: 'validFileMock',
          size: 2000000,
          type: 'image/png',
        },
        id: 'validFileMockId',
        name: 'validFileMock',
        size: 2000000,
        type: 'image/png',
        loadingStatus: 'uploading',
        progress: 100,
        errors: [],
      },
    ];
    const mockOnProgress = jest.fn();
    const mockOnChange = jest.fn();
    generateUUID.mockReturnValueOnce('1234');

    const ParentComponent = () => {
      const [value, setValue] = React.useState(mockValue);

      return (
        <FileMultiUploader
          value={value}
          hasProgress
          feedbackMessage="Done!"
          feedbackTimeout={1000}
          onProgress={mockOnProgress}
          onChange={(newValue) => {
            mockOnChange(newValue);
            setValue(newValue);
          }}
        />
      );
    };
    render(<ParentComponent />);
    expect(mockOnProgress).toHaveBeenCalled();
    expect(mockOnChange).toHaveBeenCalled();
    expect(screen.getByText('Done!')).toBeInTheDocument();
    act(() => {
      jest.advanceTimersByTime(1000);
    });
    expect(screen.getByText(mockValue[0].fileContent.name)).toBeInTheDocument();
  });

  it('should call uploadFile when a file is uploaded', async () => {
    const mockUploadFile = jest.fn().mockResolvedValue('url');
    const mockOnUpload = jest.fn();
    generateUUID.mockReturnValueOnce('1234');
    render(
      <FileMultiUploader
        value={[validFilesMock[0]]}
        multiple
        hasProgress
        uploadFile={mockUploadFile}
        onUpload={mockOnUpload}
      />
    );
    const dropzone = screen.getByTestId('drag-and-drop-area');
    const file = new File(['dummy content'], 'example.txt', { type: 'text/plain' });
    fireEvent.drop(dropzone, { dataTransfer: { files: [file] } });
    await waitFor(() => expect(mockUploadFile).toHaveBeenCalled());
    expect(mockOnUpload).toHaveBeenCalledWith({
      errors: [],
      fileContent: file,
      id: '1234',
      name: 'example.txt',
      size: 13,
      type: 'text/plain',
      loadingStatus: 'uploading',
      progress: 0,
      url: 'url',
    });
  });

  it('should handle error when uploadFile rejects', async () => {
    const mockUploadFile = jest.fn().mockRejectedValue(new Error('upload failed'));
    const mockOnUpload = jest.fn();
    generateUUID.mockReturnValueOnce('1234');
    render(
      <FileMultiUploader
        value={[validFilesMock[0]]}
        multiple
        uploadFile={mockUploadFile}
        onUpload={mockOnUpload}
      />
    );
    const dropzone = screen.getByTestId('drag-and-drop-area');
    const file = new File(['dummy content'], 'example.txt', { type: 'text/plain' });
    fireEvent.drop(dropzone, { dataTransfer: { files: [file] } });
    await waitFor(() => expect(mockUploadFile).toHaveBeenCalled());
    expect(mockOnUpload).not.toHaveBeenCalled();
    expect(screen.getAllByText('upload failed')[1]).toBeInTheDocument();
  });

  it('should handle error when uploadFile rejects without message', async () => {
    const mockUploadFile = jest.fn().mockRejectedValue(new Error());
    const mockOnUpload = jest.fn();
    const mockOnChange = jest.fn();
    generateUUID.mockReturnValueOnce('1234');
    render(
      <FileMultiUploader
        value={[validFilesMock[0]]}
        multiple
        uploadFile={mockUploadFile}
        onUpload={mockOnUpload}
        onChange={mockOnChange}
      />
    );
    const dropzone = screen.getByTestId('drag-and-drop-area');
    const file = new File(['dummy content'], 'example.txt', { type: 'text/plain' });
    fireEvent.drop(dropzone, { dataTransfer: { files: [file] } });
    await waitFor(() => expect(mockUploadFile).toHaveBeenCalled());
    expect(mockOnUpload).not.toHaveBeenCalled();
    expect(mockOnChange).toHaveBeenCalled();
    expect(screen.getAllByText('Error on upload file service.')[1]).toBeInTheDocument();
  });
});
